<script setup lang="ts">
import { onMounted, reactive, ref, watch } from "vue";
import { item, type OpenVpnOptions, type OpenVpnCapacity, type OpenVpnKeyType, type OpenVpnCipher } from "@papilio/api";
import { faNumber } from "@papilio/ui";
import NumField from "@papilio/ui/NumField.vue";
const props=defineProps<{value:OpenVpnOptions|null;disabled:boolean;editing:boolean}>();
const capacity=ref<OpenVpnCapacity|null>(null),loading=ref(false),error=ref("");
const fields=reactive({ca_name:"",server_name:"",transport:"",mode:"",network:"",bridge_address:"",pool_start:"",pool_end:"",routes:"",dns:"",redirect_gateway:"",client_to_client:"",tls_crypt:"",key_type:"",tls_min_version:"",ca_validity_days:"",server_validity_days:"",client_validity_days:"",crl_validity_seconds:"",keepalive_seconds:"",restart_seconds:"",max_clients:"",management_socket:"",verbosity:""});
const ciphers=ref<OpenVpnCipher[]>([]);
const keyNames:Record<OpenVpnKeyType,string>={ec_p256:"P-256 curve",rsa_2048:"RSA · 2048 bits",rsa_3072:"RSA · 3072 bits",rsa_4096:"RSA · 4096 bits"};
const numericFields=[{key:"ca_validity_days",label:"CA validity (days)",identity:true},{key:"server_validity_days",label:"Server certificate validity (days)",identity:true},{key:"client_validity_days",label:"New client certificate validity (days)",identity:true},{key:"crl_validity_seconds",label:"Revocation list validity (seconds)",identity:false},{key:"keepalive_seconds",label:"Connection check interval (seconds)",identity:false},{key:"restart_seconds",label:"Unresponsive connection timeout (seconds)",identity:false},{key:"max_clients",label:"Maximum concurrent clients",identity:false},{key:"verbosity",label:"Core log verbosity",identity:false}] as const;
const booleanFields=[{key:"redirect_gateway",label:"Route all traffic"},{key:"client_to_client",label:"Allow client-to-client traffic"},{key:"tls_crypt",label:"Encrypt the control channel"}] as const;
watch(()=>props.value,value=>{if(!value)return;Object.assign(fields,{...value,mode:value.topology.mode,network:value.topology.network,routes:value.routes.join(", "),dns:value.dns.join(", "),redirect_gateway:String(value.redirect_gateway),client_to_client:String(value.client_to_client),tls_crypt:String(value.tls_crypt),bridge_address:value.topology.mode==="tap"?value.topology.bridge_address:"",pool_start:value.topology.mode==="tap"?value.topology.pool_start:"",pool_end:value.topology.mode==="tap"?value.topology.pool_end:""});numericFields.forEach(({key})=>{fields[key]=String(value[key]);});ciphers.value=[...value.data_ciphers];},{immediate:true});
async function load():Promise<void>{loading.value=true;error.value="";try{capacity.value=await item<OpenVpnCapacity|null>("/v1/admin/network/configurations/openvpn-policy");}catch(cause){error.value=cause instanceof Error?cause.message:"The operation failed. Please try again.";}finally{loading.value=false;}}
function options(listen:string):OpenVpnOptions{if(!capacity.value?.enabled)throw new Error("OpenVPN creation is disabled by the operational policy.");if(!["tcp","udp"].includes(fields.transport)||!["tun","tap"].includes(fields.mode)||!capacity.value.allowed_key_types.includes(fields.key_type as OpenVpnKeyType)||!["1.2","1.3"].includes(fields.tls_min_version)||booleanFields.some(({key})=>!["true","false"].includes(fields[key]))||!ciphers.value.length)throw new Error("Choose all required OpenVPN modes.");if(numericFields.some(({key})=>fields[key]===""||!Number.isSafeInteger(Number(fields[key]))))throw new Error("Complete the OpenVPN numeric settings with valid values.");const values:OpenVpnOptions={protocol:"openvpn",listen_address:listen,ca_name:fields.ca_name,server_name:fields.server_name,transport:fields.transport as "tcp"|"udp",topology:fields.mode==="tun"?{mode:"tun",network:fields.network}:{mode:"tap",network:fields.network,bridge_address:fields.bridge_address,pool_start:fields.pool_start,pool_end:fields.pool_end},routes:fields.routes.split(",").map(s=>s.trim()).filter(Boolean),dns:fields.dns.split(",").map(s=>s.trim()).filter(Boolean),redirect_gateway:fields.redirect_gateway==="true",client_to_client:fields.client_to_client==="true",tls_crypt:fields.tls_crypt==="true",key_type:fields.key_type as OpenVpnKeyType,tls_min_version:fields.tls_min_version as "1.2"|"1.3",data_ciphers:[...ciphers.value],ca_validity_days:Number(fields.ca_validity_days),server_validity_days:Number(fields.server_validity_days),client_validity_days:Number(fields.client_validity_days),crl_validity_seconds:Number(fields.crl_validity_seconds),keepalive_seconds:Number(fields.keepalive_seconds),restart_seconds:Number(fields.restart_seconds),max_clients:Number(fields.max_clients),management_socket:fields.management_socket,verbosity:Number(fields.verbosity)};return values;}
defineExpose({options});onMounted(()=>void load());
</script>
<template><fieldset class="form-grid" :disabled="disabled||loading"><legend>OpenVPN</legend><p v-if="loading">Loading operational policy…</p><p v-if="error" class="message error" role="alert">{{error}} <button type="button" class="btn secondary" @click="load">Retry</button></p><p v-if="!loading&&!error&&!capacity?.enabled" class="message error">OpenVPN creation is disabled by the operational policy.</p><template v-if="capacity?.enabled"><p class="hint-box">A bridge requires the node bridge interface and network setup. Agent disconnection stops the managed core.</p><p>CA / server / client validity limits: {{faNumber(capacity.max_ca_validity_days)}} / {{faNumber(capacity.max_server_validity_days)}} / {{faNumber(capacity.max_client_validity_days)}} days · client capacity {{faNumber(capacity.max_clients)}}</p><label class="field"><span>CA name</span><input v-model="fields.ca_name" maxlength="64" required :disabled="editing" dir="ltr"/></label><label class="field"><span>Server certificate name</span><input v-model="fields.server_name" maxlength="64" required :disabled="editing" dir="ltr"/></label><label class="field"><span>OpenVPN transport</span><select v-model="fields.transport" aria-label="OpenVPN transport" :disabled="editing" required><option value="" disabled>Choose an option</option><option value="udp">UDP</option><option value="tcp">TCP</option></select></label><label class="field"><span>Tunnel network mode</span><select v-model="fields.mode" aria-label="Tunnel network mode" required><option value="" disabled>Choose an option</option><option value="tun">Routed TUN</option><option value="tap">Bridged TAP</option></select></label><label class="field"><span>Network range (CIDR)</span><input v-model="fields.network" dir="ltr" required/></label><template v-if="fields.mode==='tap'"><label class="field"><span>Bridge address</span><input v-model="fields.bridge_address" dir="ltr" required/></label><label class="field"><span>Bridge client range start</span><input v-model="fields.pool_start" dir="ltr" required/></label><label class="field"><span>Bridge client range end</span><input v-model="fields.pool_end" dir="ltr" required/></label></template><label class="field"><span>Network routes (CIDR, comma separated)</span><input v-model="fields.routes" dir="ltr"/></label><label class="field"><span>DNS addresses (comma separated)</span><input v-model="fields.dns" dir="ltr"/></label><label v-for="entry in booleanFields" :key="entry.key" class="field"><span>{{entry.label}}</span><select v-model="fields[entry.key]" :aria-label="entry.label" :disabled="editing&&entry.key==='tls_crypt'" required><option value="" disabled>Choose an option</option><option value="true">Active</option><option value="false">Inactive</option></select></label><label class="field"><span>Certificate key type</span><select v-model="fields.key_type" aria-label="Certificate key type" :disabled="editing" required><option value="" disabled>Choose an option</option><option v-for="kind in capacity.allowed_key_types" :key="kind" :value="kind">{{keyNames[kind]}}</option></select></label><label class="field"><span>Minimum TLS version</span><select v-model="fields.tls_min_version" aria-label="Minimum TLS version" required><option value="" disabled>Choose an option</option><option value="1.2">1.2</option><option value="1.3">1.3</option></select></label><fieldset><legend>Allowed data ciphers, in preference order</legend><label v-for="cipher in (['AES-256-GCM','AES-128-GCM','CHACHA20-POLY1305'] as const)" :key="cipher" class="check-row"><input v-model="ciphers" type="checkbox" :value="cipher"/>{{cipher}}</label></fieldset><NumField v-for="entry in numericFields" :key="entry.key" v-model="fields[entry.key]" :label="entry.label" :disabled="editing&&entry.identity"/><label class="field"><span>Private management socket path on node</span><input v-model="fields.management_socket" dir="ltr" required/></label><p v-if="editing" class="hint-box">Editing preserves certificate identity and keys. To replace the CA or transport, create a new configuration and update the group. Customer subscription URLs remain stable.</p></template></fieldset></template>
<style scoped>fieldset{min-inline-size:0;border:0;padding:0;margin:0;display:grid;gap:14px}legend{font-weight:700}</style>
